            visited[node] = True
            for neighbor in graph.get(node, set()):
                current_order = max(current_order, dfs(neighbor, current_order))
            return current_order

        for node in range(-n, n + 1):
            if not visited[node]:
                order += dfs(node, 0)

        return order

